pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 1 ether);

        // install an adversarial log through the public SetLogFile entry point
        RevertingLog log = new RevertingLog();
        c.SetLogFile(address(log));

        // depositing must go through the installed log: since its AddMessage
        // reverts, the reference C reverts on Deposit for EVERY admissible
        // (actor, amount); the mutant never installed the log, so it succeeds
        // for some inputs.
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Deposit{value: amount}() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

contract RevertingLog {
    function AddMessage(address, uint256, string calldata) external pure {
        revert();
    }
}

