    function testFuzz_property(address logTarget, uint256 amount, address actor) public {
        // The domain is the full admissible space: any log target, any amount, any actor.
        vm.assume(actor != address(0));

        // Drive the difference through the public entry point SetLogFile
        // (contract is still uninitialized, so the call must succeed on both versions).
        c.SetLogFile(logTarget);

        // General rule: the stored Log address must always be a real (nonzero) address
        // so that log messages can be delivered to it. The mutant stores address(0),
        // violating this for every admissible input.
        vm.deal(actor, amount);
        assertTrue(c.Log() != address(0));
    }
}

